Method.Implementation:
Set tStatus = $$$OK
Try {
	Set seqKey = ""
	For {
		Set tElement = ..Records.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.OutCB.Body).PutObject(pIOStream,tElement,0)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = ..Records.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	Set tId = ..%Id()
	If ""=tId {
		Set seqKey = ""
		For {
			Set tElement = ..Records.GetNext(.seqKey)
			If (seqKey = "") Quit
			If $IsObject(tElement) && (""'=tElement.%Id()) {
				Set tElementId = tElement.%Id()
				Set tStatus = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.OutCB.Body.Record).%DeleteId(tElementId)
			}
			If $$$ISERR(tStatus) Quit
		}
	}
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus
